-- Generated by model/lib/sql/generate.mjs. L1's load of IMPORT List Price from cells/IMPORT List Price.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/IMPORT List Price.csv
INSERT INTO "IMPORT List Price" SELECT coalesce(k0."SKU", fpabench_error('cells name a member SKU does not have: ' || c."SKU")), coalesce(k1."Country", fpabench_error('cells name a member Country does not have: ' || c."Country")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Country" k1 ON k1.name = c."Country" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4;
ANALYZE "IMPORT List Price";
